package com.iamgasgass.gassplayer.services
import android.content.Context
import java.security.MessageDigest
class ParentalLockManager(context:Context){private val prefs=context.getSharedPreferences("parental",Context.MODE_PRIVATE);private fun hash(v:String)=MessageDigest.getInstance("SHA-256").digest(v.toByteArray()).joinToString(""){"%02x".format(it)};fun enabled()=prefs.getBoolean("enabled",false);fun setPin(pin:String){require(pin.length>=4);prefs.edit().putString("pin",hash(pin)).putBoolean("enabled",true).apply()};fun verify(pin:String)=prefs.getString("pin",null)==hash(pin);fun lock(id:String){prefs.edit().putStringSet("locked",prefs.getStringSet("locked",emptySet()).orEmpty()+id).apply()};fun unlock(id:String){prefs.edit().putStringSet("locked",prefs.getStringSet("locked",emptySet()).orEmpty()-id).apply()};fun isLocked(id:String)=enabled()&&id in prefs.getStringSet("locked",emptySet()).orEmpty();fun disable(pin:String):Boolean=verify(pin).also{if(it)prefs.edit().clear().apply()}}
